Select.items:
{
                                    path: '/Persons',
                                    parameters: {
                                        $select: 'ID,Name,Income,ExpenseTarget,Currency,ImageType,IsActiveEntity',
                                        $expand: 'DraftAdministrativeData($select=DraftUUID,InProcessByUser)',
                                        $filter: '(IsActiveEntity eq false or SiblingEntity/IsActiveEntity eq null)'
                                    }
                                }

Text.text:
{
                                                parts: [{
                                                    path: 'i18n>transactionTotalLabel'
                                                }, {
                                                    path: 'ui>TotalAmount'
                                                }, {
                                                    path: 'ui>Amount'
                                                }, {
                                                    path: 'ui>Currency'
                                                }],
                                                formatter: 'formatter.formatTotalWithLabel'
                                            }
